if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{if(!$canManage)throw new RuntimeException('ไม่มีสิทธิ์อนุมัติคำขอลา');$id=(int)($_POST['leave_id']??0);$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['admin_note']??''));if(!in_array($decision,['approved','rejected'],true))throw new RuntimeException('สถานะไม่ถูกต้อง');$found=false;$notifyUser=0;$employeeId=0;$type='';$range='';db_mutate(function($x)use($id,$decision,$note,$u,&$found,&$notifyUser,&$employeeId,&$type,&$range){foreach($x['leave_requests'] as &$l){if((int)($l['id']??0)!==$id)continue;if(($l['status']??'')!=='pending')throw new RuntimeException('คำขอนี้ถูกดำเนินการแล้ว');$l['status']=$decision;$l['admin_note']=$note;$l['reviewed_by']=(int)$u['id'];$l['reviewed_at']=date('c');$l['updated_at']=date('c');$found=true;$notifyUser=(int)($l['user_id']??0);$employeeId=(int)($l['employee_id']??0);$type=(string)$l['type'];$range=(string)$l['start_date'].' → '.(string)$l['end_date'];break;}unset($l);if($found){audit_permission($x,$u,'leave_reviewed',['leave_id'=>$id,'employee_id'=>$employeeId,'decision'=>$decision]);$txt=$decision==='approved'?'อนุมัติแล้ว':'ไม่อนุมัติ';op_notify($x,$notifyUser?:null,'staff','leave_status','คำขอ'.al_type($type).' '.$range.' '.$txt,['leave_id'=>$id,'status'=>$decision,'employee_id'=>$employeeId]);}return $x;});if(!$found)throw new RuntimeException('ไม่พบคำขอลา');$msg=$decision==='approved'?'อนุมัติคำขอลาแล้ว':'ปฏิเสธคำขอลาแล้ว';}catch(Throwable $e){$err=$e->getMessage();}$d=db_load();}
$status=(string)($_GET['status']??'pending');if(!in_array($status,['all','pending','approved','rejected','cancelled'],true))$status='pending';$employeeFilter=(int)($_GET['employee_id']??0);$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');
$rows=[];foreach($d['leave_requests']??[] as $l){$eid=(int)($l['employee_id']??0);if(!$eid&& !empty($l['pr_id']))$eid=(int)(workforce_employee_by_pr($d,(int)$l['pr_id'])['id']??0);if($status!=='all'&&($l['status']??'')!==$status)continue;if($employeeFilter&&$eid!==$employeeFilter)continue;if(substr((string)($l['start_date']??''),0,7)!==$month&&substr((string)($l['end_date']??''),0,7)!==$month)continue;$l['_employee_id']=$eid;$rows[]=$l;}usort($rows,function($a,$b){return strcmp((string)($b['requested_at']??''),(string)($a['requested_at']??''));});
$countPending=count(array_filter($d['leave_requests']??[],function($l){return ($l['status']??'')==='pending';}));$countApproved=count(array_filter($d['leave_requests']??[],function($l)use($month){return ($l['status']??'')==='approved'&&substr((string)($l['start_date']??''),0,7)===$month;}));$countSick=count(array_filter($d['leave_requests']??[],function($l)use($month){return ($l['type']??'')==='sick'&&substr((string)($l['start_date']??''),0,7)===$month;}));
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MR BAR — Leave Requests</title><link rel="stylesheet" href="assets/admin.css?v=1180"><link rel="stylesheet" href="assets/admin-leaves.css?v=1180"><link rel="stylesheet" href="assets/admin-v14.css?v=1180"></head><body class="admin-v14-page"><?php require_once __DIR__.'/app/admin-nav.php';echo admin_sidebar('leaves',$u);?><main class="leave-admin"><header class="la-head"><div><p>ADMIN / WORKFORCE / LEAVE</p><h1>Leave Request Center</h1><span>PR / Staff / Manager / Office ใช้ศูนย์อนุมัติเดียวกัน</span></div><div><a href="employees.php">Employees</a><a href="workforce-schedule.php">Workforce Schedule</a><a href="payroll-attendance.php">Payroll</a></div></header><?php if($msg):?><div class="la-note ok">✓ <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="la-note err">⚠ <?=h($err)?></div><?php endif;?><section class="la-kpis"><article><small>รออนุมัติทั้งหมด</small><b><?=$countPending?></b></article><article><small>อนุมัติเดือนนี้</small><b><?=$countApproved?></b></article><article><small>ลาป่วยเดือนนี้</small><b><?=$countSick?></b></article></section><section class="la-filter"><form method="get"><label>เดือน<input type="month" name="month" value="<?=h($month)?>"></label><label>สถานะ<select name="status"><option value="all" <?=$status==='all'?'selected':''?>>ทั้งหมด</option><option value="pending" <?=$status==='pending'?'selected':''?>>รออนุมัติ</option><option value="approved" <?=$status==='approved'?'selected':''?>>อนุมัติ</option><option value="rejected" <?=$status==='rejected'?'selected':''?>>ไม่อนุมัติ</option><option value="cancelled" <?=$status==='cancelled'?'selected':''?>>ยกเลิก</option></select></label><label>พนักงาน<select name="employee_id"><option value="0">ทุกคน</option><?php foreach($d['employees']??[] as $e)if(!empty($e['active'])):?><option value="<?=(int)$e['id']?>" <?=$employeeFilter===(int)$e['id']?'selected':''?>><?=h((string)$e['code'].' · '.(string)$e['name'])?></option><?php endif;?></select></label><button>แสดงรายการ</button></form></section><section class="la-list"><?php if(!$rows):?><div class="la-empty">ไม่มีคำขอลาตามตัวกรองนี้</div><?php endif;?><?php foreach($rows as $l):$e=al_emp($d,(int)$l['_employee_id']);?><article class="la-card status-<?=h((string)$l['status'])?>"><div class="la-person"><span><?=h(substr((string)$e['code'],0,3))?></span><div><small><?=h((string)$e['code'].' · '.workforce_position_label((string)$e['position']))?></small><h2><?=h((string)$e['name'])?></h2><em><?=h(al_status((string)$l['status']))?></em></div></div><div class="la-info"><b><?=h(al_type((string)$l['type']))?></b><strong><?=h(date('d/m/Y',strtotime((string)$l['start_date'])))?><?=($l['start_date']??'')!==($l['end_date']??'')?' → '.h(date('d/m/Y',strtotime((string)$l['end_date']))):''?></strong><span><?=h(al_portion((string)$l['portion']))?> · ส่ง <?=h(date('d/m/Y H:i',strtotime((string)$l['requested_at'])))?></span><p><?=nl2br(h((string)$l['reason']))?></p><?php if(!empty($l['admin_note'])):?><div class="admin-note">หมายเหตุ Admin: <?=h((string)$l['admin_note'])?></div><?php endif;?></div><div class="la-actions"><?php if(($l['status']??'')==='pending'&&$canManage):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="leave_id" value="<?=(int)$l['id']?>"><textarea name="admin_note" placeholder="หมายเหตุถึงพนักงาน (ถ้ามี)"></textarea><div><button class="approve" name="decision" value="approved">✓ อนุมัติ</button><button class="reject" name="decision" value="rejected">× ไม่อนุมัติ</button></div></form><?php else:?><span class="final-status <?=h((string)$l['status'])?>"><?=h(al_status((string)$l['status']))?></span><?php if(!empty($l['reviewed_at'])):?><small><?=h(date('d/m/Y H:i',strtotime((string)$l['reviewed_at'])))?></small><?php endif;?><?php endif;?></div></article><?php endforeach;?></section><footer>MR BAR Workforce L